-- c006-v001: E vi quando abriu o Cordeiro um dos – sete selos e ouvi um dos – quatro seres–viventes dizendo como voz de–trovão Vem
-- c006-v002: E vi e eis cavalo branco e o sentado sobre ele tendo arco e foi–dada a–ele coroa e saiu vencendo e para vencer
-- c006-v003: E quando abriu o selo – segundo ouvi o segundo ser–vivente dizendo Vem
-- c006-v004: E saiu outro cavalo vermelho e ao sentado sobre ele foi–dado a–ele tirar a paz da – terra e para–que uns–aos–outros matem e foi–dada a–ele espada grande
-- c006-v005: E quando abriu o selo – terceiro ouvi o terceiro ser–vivente dizendo Vem e vi e eis cavalo preto e o sentado sobre ele tendo balança na – mão dele
-- c006-v006: E ouvi como voz no meio dos quatro seres–viventes dizendo Medida–de–trigo de–trigo por–um–denário e três medidas de–cevada por–um–denário e o azeite e o vinho não danifiques
-- c006-v007: E quando abriu o selo – quarto ouvi voz do quarto ser–vivente dizendo Vem
-- c006-v008: E vi e eis cavalo amarelo e o sentado em–cima dele nome a–ele A Morte e o Hades seguia com ele e foi–dada a–eles autoridade sobre a quarta–parte da terra para–matar com espada e com fome e com morte e pelas – feras da terra
-- c006-v009: E quando abriu o quinto selo vi debaixo do altar as almas dos imolados por–causa–de a palavra – de–Deus e por–causa–de o testemunho que tinham
-- c006-v010: e clamaram em–voz grande dizendo Até quando ó Soberano – santo e verdadeiro não julgas e vingas o sangue nosso dos – que–habitam sobre a terra
-- c006-v011: E foi–dada a–eles a–cada–um veste branca e foi–dito a–eles que descansassem ainda tempo pouco até–que se–completem também os conservos deles e os irmãos deles os que–estão–para ser–mortos como também eles
-- c006-v012: E vi quando abriu o selo – sexto e terremoto grande houve e o sol tornou-se negro como saco de–pelo e a lua toda tornou-se como sangue
-- c006-v013: e as estrelas do céu caíram para a terra como figueira lança os figos–verdes dela por vento grande sendo–sacudida
-- c006-v014: e o céu afastou-se como livro enrolado e todo monte e ilha dos – lugares deles foram–movidos
-- c006-v015: E os reis da terra e os grandes e os comandantes e os ricos e os fortes e todo escravo e livre esconderam-se a–si–mesmos nas – cavernas e nas – rochas dos montes
-- c006-v016: e dizem aos montes e às rochas Caí sobre nós e escondei-nos –nos da face do sentado sobre o trono e da – ira do Cordeiro
-- c006-v017: porque chegou o dia – grande da ira deles e quem pode ficar–em–pé

